// Robust Payload Normalizer: handles buffer, raw string, or parsed JSON
const raw = $input.first().json;
let payload = {};

if (raw.content) {
  if (typeof raw.content === 'string') {
    try {
      payload = JSON.parse(raw.content);
    } catch (e) {
      payload = { text: raw.content };
    }
  } else if (typeof raw.content === 'object') {
    payload = raw.content;
  }
} else {
  payload = raw;
}

const eventType = payload.eventType || raw.eventType || raw.fields?.routingKey || 'unknown';
const data = payload.data || payload;
const leadId = data.leadId || payload.leadId || null;
const workflowRunId = data.workflowRunId || payload.workflowRunId || null;

// Qualification is targeted when eventType matches or leadId is explicitly provided
const isQualificationEvent = eventType === 'lead.qualification.requested' || (!payload.eventType && !!leadId);
const isValid = !!leadId && isQualificationEvent;

return [{
  json: {
    eventId: payload.eventId || 'evt-' + Date.now(),
    eventType,
    leadId,
    workflowRunId,
    isQualificationEvent,
    isValid,
    routingStatus: isValid ? 'ROUTE_TO_AI' : 'SKIP_NON_QUALIFICATION',
    receivedAt: new Date().toISOString(),
    rawPayload: payload
  }
}];

const lead = $input.first().json;
const meta = $('⚙️ Normalize Event Payload').first().json;

const prompt = `
You are an enterprise B2B Lead Qualification AI Assistant for a CRM Automation platform.
Evaluate the following incoming lead using B2B ICP (Ideal Customer Profile) and BANT framework:

Contact: ${lead.firstName} ${lead.lastName || ''}
Email: ${lead.email}
Phone: ${lead.phone || 'N/A'}
Company: ${lead.companyName || 'Not specified'}
Website: ${lead.companyWebsite || 'Not specified'}
Job Title: ${lead.jobTitle || 'Not specified'}
Industry: ${lead.industry || 'Not specified'}
Company Size: ${lead.companySize || 'Not specified'}
Notes: ${lead.notes || 'None'}

Evaluation Rules:
1. Qualification Status must be one of: "QUALIFIED", "DISQUALIFIED", "NEEDS_REVIEW".
2. Confidence score must be a number between 0.00 and 1.00.
3. If decision maker level (Director, Manager, C-level) and company size > 10, confidence >= 0.85.
4. If personal email (gmail/yahoo) or missing company, confidence should be lower and set reviewRequired to true.

Respond ONLY in this exact JSON schema:
{
  "qualification": "QUALIFIED" | "DISQUALIFIED" | "NEEDS_REVIEW",
  "confidence": 0.90,
  "intent": "Brief summary of customer purchase intent",
  "reason": "Detailed rationale behind this evaluation",
  "nextAction": "Actionable recommended sales step",
  "reviewRequired": false
}
`;

return [{
  json: {
    leadId: lead.id,
    workflowRunId: meta.workflowRunId,
    leadProfile: lead,
    prompt
  }
}];

const response = $input.first().json;
const prep = $('🧠 Synthesize B2B Prompt').first().json;

let aiOutput;
try {
  const content = response.candidates?.[0]?.content?.parts?.[0]?.text || '{}';
  aiOutput = JSON.parse(content);
} catch (err) {
  aiOutput = {
    qualification: 'NEEDS_REVIEW',
    confidence: 0.50,
    intent: 'Failed to parse AI structured response',
    reason: 'Model output did not conform to JSON specification',
    nextAction: 'Manual sales inspection required',
    reviewRequired: true
  };
}

const confidence = typeof aiOutput.confidence === 'number' ? aiOutput.confidence : 0.50;
const reviewRequired = confidence < 0.80 || aiOutput.qualification === 'NEEDS_REVIEW' || aiOutput.reviewRequired === true;

return [{
  json: {
    leadId: prep.leadId,
    workflowRunId: prep.workflowRunId,
    status: aiOutput.qualification || 'NEEDS_REVIEW',
    intent: aiOutput.intent || 'B2B CRM Consultation',
    confidence: Math.min(1, Math.max(0, confidence)),
    reason: aiOutput.reason || 'AI automated assessment',
    nextAction: aiOutput.nextAction || 'Contact prospect',
    reviewRequired,
    modelProvider: 'google',
    modelName: $env.GEMINI_MODEL || 'gemini-1.5-pro',
    modelVersion: 'v1beta',
    inputSnapshot: prep.leadProfile,
    outputSnapshot: aiOutput,
    evaluatedAt: new Date().toISOString()
  }
}];

const callbackRes = $input.first().json;
const decision = $('📊 Evaluate Confidence Gate').first().json;

return [{
  json: {
    auditStatus: 'QUALIFICATION_SUCCESS',
    leadId: decision.leadId,
    assignedStatus: decision.status,
    confidenceScore: decision.confidence,
    requiresHumanReview: decision.reviewRequired,
    model: decision.modelName,
    completedAt: new Date().toISOString(),
    backendResponse: callbackRes
  }
}];

const meta = $('⚙️ Normalize Event Payload').first().json;

return [{
  json: {
    auditStatus: 'EVENT_SKIPPED_SAFELY',
    eventId: meta.eventId,
    receivedEventType: meta.eventType,
    leadId: meta.leadId || 'N/A',
    reason: meta.leadId ? `Event type '${meta.eventType}' does not trigger AI Qualification (targeted only for 'lead.qualification.requested')` : 'Payload missing leadId identifier.',
    actionTaken: 'Safely acknowledged and dropped without consuming LLM API tokens',
    loggedAt: new Date().toISOString()
  }
}];
